def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([-5]), fmt([0]), fmt([4, -6, 3, -2, 5]), fmt([2, 3, 5]), fmt([-1, -1, -1]),
             fmt([-10000, 10000]), fmt([10000, -10000, -10000])]
    for n in (2, 3, 5, 8, 12, 20, 40):
        for lim in (3, 20, 10000):
            tests.append(fmt([rng.randint(-lim, lim) for _ in range(n)]))
    N = 100000
    tests.append(fmt([-10000] * N))
    tests.append(fmt([rng.randint(-10000, 10000) for _ in range(N)]))
    tests.append(fmt([rng.randint(-10000, 9000) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 10000) for _ in range(N)]))
    tests.append(fmt([10000] * 50000 + [-10000] * 50000))
    return tests
